from common import *
B='013红月亮.txt'
make('redmoon_envoy','红月亮白衣接待者',B,
'这位未留姓名的外星接待者，是八名先遣者中能够与卫斯理直接交流的一人。他用白色人形装置隐藏与人类完全不同的身体，接待来客时讲究秩序，甚至把预定的灭绝解释成替人类免除痛苦。他知道自己的族群因征服疾病而人口过多，认定占据地球是长期准备后的必要选择；对同伴的生命虽然珍惜，却明确愿为计划牺牲一人，令卫斯理和巴图的人质威胁失效。他能借基地仪器清除特定记忆，利用当地人后又清除知情者，但技术并不等于无所不知：保护头部的金属假发保住了卫斯理的记忆，族群对地球细菌的脆弱更成为决定性漏洞。卫斯理把老鼠送往其母星，造成巨大死亡后，移民压力消失，他最后带着悲愤宣告放弃计划并指责对方犯下罪行。综合卡保留这个会以善意包装侵略、也真实感受同类惨剧的矛盾人物。不能把母星科技全收作个人权能，更不能因最终撤退就抹去此前对人类的灭绝方案。',
'母星受鼠携细菌侵袭，人口锐减；向卫斯理说明停止移民计划后离开。','异星防护装置、基地技术与谈判','白衣是可移动密封装置；在基地可操作记忆光束及传送、通讯设施，以知识与技术压制对手。','须依赖完整设备，记忆处理可被金属防护阻挡；本体怕地球微生物，基地与母星级手段不是随身能力。',[(1931,1991,'记忆仪器与假发防护'),(2602,2609,'白衣实际为装置'),(2661,2713,'同伴与移民决心'),(2940,2982,'细菌弱点'),(2983,3039,'灭绝计划'),(3173,3181,'母星灾难及最终撤退')],
'为族群解决生存空间问题，习惯以技术优势与理性措辞使暴力显得必然。',[('对手以同伴为人质','任务被视为全族利益','愿付出有限牺牲，不轻易放弃计划。'),('外界生命质疑灭绝','仍相信本族优越判断','试图辩护其所谓无痛善意，须面对被害者反驳。'),('族群受到不可逆伤害','迁移理由已经改变','停止既定行动但保留悲痛与追责。')],roles=['反派'],scores=(3,3,3,4,3,3),tier='准神',limits=(3,5,1),appearance='外表为白色人形密封装置；本体约四呎高、有触须和蓝色发光器官，不是穿白衣的地球人。',durability='白衣提供技术防护；裸露本体易受地球微生物伤害，非不死。',speed='依白衣移动，本体适合水中行动；远距传送依基地。',energy='使用技术装置，无内生无限能量。',stamina='依密封环境与设备维持安全。')
make('puna','普娜',B,
'普娜原是黑手党重要打手，曾获得女子摔角冠军，以强大体重、力量和贴身扑击形成威胁。她出现在小镇餐饮场所，以洗手不干的说法应付卫斯理，却实际替神秘白衣人做事，既能搬动强壮的巴图，也熟悉用隐蔽设施交接俘虏。她对金钱敏感，但并非听到价码便失去判断：面对卫斯理的收买，先想到泄密处罚，再要求现金以免支票被止付，显示犯罪经验中的实用谨慎。她对上级的恐惧最终是有根据的。白衣人完成调查后清除受雇者，她与另一店主被杀；她得到过的好处没有变成真正保护。综合卡恢复最后清醒的摔角手与黑帮执行者，保留对威慑、利益和自保的权衡。飞行的桌面属于外星设施，不是她能飞行或隔空搬人的能力；身体强壮也不等于能抵御外星杀人手段。在新情境中，她可以因价码、退路与受骗程度改变合作对象，而不必每次都只重复莽撞冲撞。',
'因替白衣人办事而成为灭口对象，在小镇被杀。','摔角、强力搬运与犯罪交涉','训练、体重和力量支持近身擒抱扑击，犯罪经历使其会核验支付与背叛风险。','只在近身形成优势，不能把外星桌台当作个人飞行装备；技术杀伤和背后灭口无法硬扛。',[(1374,1399,'身份、力量与交接'),(1418,1474,'摔角扑击和现金交涉'),(1538,1548,'遭灭口'),(2116,2118,'受雇者与清除关系')],
'获得可落袋的收益，同时避免因泄密或倒戈被上级清除。',[('对手进入擒抱距离','有身体优势','以猛扑和压制快速控制。'),('有人收买秘密','惩罚风险明确','先比较退路和现金保障。'),('上级准备清场','自己也是知情人','优先寻找脱离与保护，不因旧效忠自动安全。')],roles=['反派'],scores=(3,0,0,3,1,3),tier='并',dead=True,appearance='体形高大肥壮，扑击时可压碎椅子的女子。')
make('shiwan','史万探长',B,
'史万是蒂卡隆镇的警探，以看似迟缓的姿态处理外来者，实际会用证件检查、地方权力和试探掌握情况。他把警察身份变成神秘集团在人间的便利，接受白衣人的利益，并指挥部分替集团办事的人。面对卫斯理时，他并不坦白自己的关系，显示有意把调查者留在可控制的叙述中。然而这种依附并没有让他理解真正雇主的规模，也没有带来平等地位。当其他受雇者接连从峭壁跌落或暴毙，他惊惶地闯入卫斯理房间，反复请求保护，期望借自己曾经为难的人逃过清除。他未能说出有效的逃生办法，最终就在房间里窒息般发作并死亡。综合卡恢复最后清醒的地方探长，保留受贿、控制与求生的完整因果，而不把末日恐惧当作洗清责任。他能在熟悉辖区制造手续障碍，却没有外星人的远程杀伤或记忆技术；真正的戏剧空间来自他在继续装作知情与承认自己只是可弃工具之间的挣扎。',
'同党被清除后向卫斯理求救，在其房间中发作死亡。','地方警务与受雇者联络','凭警察身份检查证件、干预调查并联系受雇人员，熟悉辖区情况。','权力依赖具体辖区和组织合作；并不掌握外星技术，更不能以警察身份免除雇主清除。',[(275,321,'探查身份与警务姿态'),(2090,2111,'求援及下属关系'),(2116,2134,'受雇原因和死亡')],
'维持地方控制并从秘密合作中获益，危险临近时首先保全自己。',[('外地人追问异常','仍能利用职权','以手续和盘问限制其行动。'),('受雇伙伴接连死亡','察觉被当作弃子','抛开威风向有能力者求救。'),('盟友要求坦白','隐瞒会失去最后保护','在自保与承认责任之间作具体选择。')],roles=['反派'],scores=(1,0,1,1,2,2),tier='并',dead=True,appearance='身材肥胖，常给人迟钝或困倦印象的地方探长。')
make('baoer','保尔',B,
'保尔是《搜寻》杂志的摄影记者，也是红月亮事件的目击者之一。他因工作来到小镇，能够把观察和时间差转化为可供调查的线索，与卫斯理、巴图一度构成共同追索异常的三人关系。他并没有两位冒险者同样的战斗背景，主要价值在摄影、资料和作为外部见证者对事件的确认。白衣人的仪器清除了他关于红月亮的记忆，也破坏了三人赖以共同判断的事实基础。醒来后的保尔坚持自己只是来摄影，对卫斯理反复描述的危险感到不耐烦；在被允许离开时，他提起行李退出了调查。综合卡应把这种拒绝放回记忆被干预的处境，不能照搬叙述者对他轻佻逐利的愤怒评价作为全部人格。他最后仍是正常活动的记者，但没有恢复全部被删记忆的明证。作为终局参战人物，他可以知道事件后来被说明的真相，同时必须区分别人告知的知识和亲自记得的体验；重新建立信任需要可验证的材料，而不是要求他凭友谊承认一段空白。',
'记忆被清除后拒绝继续听卫斯理说明，带行李离开调查。','摄影报道与目击核对','用摄影工作和目击经验记录异常，能从时间信息发现不一致。','没有自主恢复被删记忆或抵抗脑部仪器的能力；终局知识不能伪装成未失去的亲历记忆。',[(833,866,'记者身份及时间差线索'),(1974,2006,'醒来与记忆缺失'),(2039,2054,'明确退出')],
'以自己能核实的材料理解事件，不愿无限追随无法回忆和验证的说法。',[('出现可拍摄的异常','条件允许记录','先取得图像和观察资料。'),('有人要求承认记忆外事件','缺乏独立证据','保留怀疑并要求可核材料。'),('调查耗费超过预期','自己有退出选择','会退出，但可被新的事实重新吸引。')],roles=['单书主角'])
cov(B,[('巴图','weisili_batu','重要配角','调查、失忆后再合作与基地反击'),('白衣接待者','redmoon_envoy','反派','八名先遣者中的可交流主导者'),('普娜','puna','反派','黑帮执行和秘密交接'),('史万','shiwan','反派','警务掩护及受雇者指挥'),('保尔','baoer','单书主角','目击、摄影与失忆退出')],[('另一吃食店老板、其余受雇者和七名白衣同伴','多为未命名执行或同群体成员；本批以独立讲话并主导决定的接待者为主卡，设备与同伴支持必须在场。')],['鼠被送返母星造成巨大伤亡是真正结局，不能只记录一次无代价的英雄胜利；外星物种的道德辩词不是客观正当性。'])
